using System;
using System.Collections.ObjectModel;

// Shared material registry. Workbench support does not automatically unlock stock or recipes.
public static class ForgeMaterialGuide
{
    public static bool IsHandleMaterial(int material) => material==1 || material==2 || material==5 || material==7;
    public const string HandleMaterials = "철(1), 나무(2), 은(5), 별철(7)";
    public static Entry Find(int number) => number>=0&&number<Entries.Count?Entries[number]:null;
    public sealed class Entry
    {
        public readonly int Number;
        public readonly string Name,Status,Description;
        public Entry(int number,string name,string status,string description)
        {Number=number;Name=name;Status=status;Description=description;}
        public string Heading => Number+" · "+Name;
    }
    public static readonly ReadOnlyCollection<Entry> Entries=Array.AsReadOnly(new[]{
        new Entry(0,"공기","현재 사용 가능","공기 자체를 작업대에 올릴 수 있으며 재고는 소비하지 않습니다. 1(0)은 0G입니다.\n냉각에 사용하면 작업물의 열을 0으로 내립니다.\n비용: 0G\n사용법: 4(Blade, 0)"),
        new Entry(1,"철","현재 사용 가능","검날의 바탕이 되는 재료입니다. 작업대에 올리면 새 작업물이 만들어집니다.\n소비: 철 1개 (골드 소비 없음)\n사용법: Blade = 1(1)\n손잡이 제작: 5(Item, 1) · 철 1개 추가 소비 · 판매가 +2G"),
        new Entry(2,"나무","기본 공급 · 재고 구매 필요","5(Item, 2)로 나무 1개를 사용해 손잡이를 만듭니다. 판매가 보너스는 +22G입니다. 봉인 201(검날,3)의 재료로도 사용합니다."),
        new Entry(3,"물","기본 공급 · 재고 구매 필요","4(검날,3)에 사용하는 냉각용 재료입니다. 사용 직전 작업물의 상태에 따라 담금질 효과가 달라지는 규칙입니다."),
        new Entry(4,"석탄","8() 화로와 묶음 해금 · 재고 구매 필요","8(온도)로 화로를 100~1200°C로 설정할 때 석탄 1개를 사용합니다. 이후 2(작업물)로 검을 가열합니다. 201(작업물,1)의 열 봉인에도 사용합니다."),
        new Entry(5,"은","전용 가공 지원 · 해금 및 재료 필요","5(Item, 5)로 은 1개를 사용해 손잡이를 만들 수 있습니다. 판매가 보너스는 +57G입니다. 식힌 검날을 연마한 뒤 도금하는 재료이기도 합니다. 연마 전에 도금하면 은을 소비하고 얼룩이 남는 규칙입니다."),
        new Entry(6,"마력 수정","전용 가공 지원 · 해금 및 재료 필요","마력 가공에 사용하는 재료입니다. 재료 상점에서 개당 30G로 구매합니다. 충전·룬 각인·마력 단조 등에 사용하며, 충전 방법과 이익은 9() 마력 충전 안내를 확인하세요."),
        new Entry(7,"별철","전용 가공 지원 · 해금 및 재료 필요","【기본 규칙】\n별철은 칼날에 사용하는 재료입니다. StarIron = 1(7)로 작업대에 올립니다. 처음 만들어질 때 숨은 별빛 값 5개(각각 정수 0~9)를 갖습니다. 읽거나 코드를 이어 실행해도 같은 작업물의 최초 값은 바뀌지 않습니다. 1(7)을 다시 호출하면 재료를 소비해 새 별철을 만듭니다.\n0은 불순물입니다. 하나라도 남으면 별빛 정제 보너스는 0G입니다. 0을 없애고, 같은 숫자는 하나만 남긴 뒤 오름차순으로 정렬하세요. 최초 배열에 있던 0 이외의 숫자 종류를 모두 보존해야 최고 정제 보너스 +120G를 받습니다. 중복·내림차순·유효 숫자 손실·빈 배열·최초 값이 전부 0인 경우에는 정제 보너스가 없습니다.\n기존 별철 가치와 별무늬 효과는 별개입니다. 성형한 별철 검날을 정확히 900°C에서 냉각하면 별무늬가 생깁니다. 기존 손잡이 제작 5(Item, 7)도 사용할 수 있습니다.\n\n【함수 표 · 위치는 0부터】\n70(StarIron) → 현재 개수(정수). 값은 바꾸지 않습니다.\n71(StarIron, Index) → 해당 위치의 값(정수 0~9). 값을 공개하며 배열은 바꾸지 않습니다.\n72(StarIron, A, B) → None. 원본의 두 위치를 교환합니다.\n73(StarIron, Index) → None. 원본에서 해당 위치를 제거하고 뒤의 값들을 한 칸 앞으로 옮깁니다.\nStarIron은 별철 작업물, Index/A/B는 0 이상 현재 개수 미만의 정수입니다. 인자 수·자료형·범위가 틀리면 그 호출은 변경이나 추가 시간 없이 해당 줄에서 오류를 안내합니다. 자동 정렬·중복 제거·값 덮어쓰기 함수는 없습니다.\n\n【짧은 예시】\n[5, 0, 2, 5, 2]\n→ 불순물 제거: [5, 2, 5, 2]\n→ 오름차순 정렬: [2, 2, 5, 5]\n→ 중복 제거: [2, 5]\n다음 숫자 코드는 0만 제거하는 예시입니다. 연습에서는 준비된 StarIron에 바로 실행하세요. 실제 제작에서는 앞에 StarIron = 1(7)을 작성하세요.\ni = 0\n888(i < 70(StarIron)):\n    1?(71(StarIron, i) == 0):\n        73(StarIron, i)\n    0?:\n        i = i + 1\n정렬과 중복 제거도 조건문과 반복문으로 직접 구성하세요. 일반 제작의 조건·반복문은 제어문 연구가 필요하며, 이 연습에서는 미리 사용할 수 있습니다.\n\n【연습과 실행 표시】\n이 페이지 아래의 ‘별철 연습’ 버튼 또는 가공 창의 ‘연습 시작 · 현재 별철 복제’를 누르세요. 연습 도면에서 StarIron은 준비된 복제 재료입니다. ‘연습 코드 실행’으로 계속 가공하고 ‘초기 상태로 되돌리기’로 같은 최초 배열을 다시 연습합니다. 복구하면 실행 및 대기 작업이 취소되고, 공개 상태·강조·횟수·예상 시간·보너스 표시가 초기화됩니다. 실제 재료·골드·판매 결과는 바뀌지 않습니다. 일반 제작에는 이 복구가 적용되지 않습니다.\n화면의 [위치: ?]는 아직 읽지 않은 값, 【위치: 값】은 동작 대상입니다. 70은 개수, 71은 해당 위치와 공개 값, 72는 교환할 두 위치와 변경 결과, 73은 제거 위치와 당겨진 배열을 표시합니다. 공개 상태는 별빛과 함께 이동하거나 삭제됩니다. 빠른 실행은 줄 번호가 있는 실행 기록으로도 확인하세요. 긴 내용은 창 안에서 스크롤합니다.\n교환·제거가 적을수록 실제 가공 시간이 짧습니다. 같은 최종 배열은 같은 품질 보너스를 받습니다. 기본 교환 0.4초·제거 0.25초(속도 1배 기준, 설정에 따라 변경). 읽기는 추가 가공 시간이 없고, 잘못된 호출과 같은 위치 교환도 무료입니다. 서로 다른 위치의 같은 값끼리 교환해도 작업 횟수와 시간을 사용합니다. 연습에는 같은 기준의 예상 시간만 표시됩니다.\n\n【주의사항】\n제거 직후 뒤의 값이 같은 위치로 이동합니다. 무조건 다음 위치로 넘어가면 값을 놓칠 수 있으므로 그 위치를 다시 확인하세요.\n[2, 5]에서 5까지 제거해 [2]로 만들면 유효 숫자를 잃었으므로 최고 보너스를 받을 수 없습니다.\n이미 공개한 값을 다시 읽어도 최초 값이 다시 생성되지 않습니다. 모든 함수를 반복 호출해도 보너스가 누적해서 붙지 않습니다."),
        new Entry(8,"서리수","전용 가공 지원 · 해금 및 재료 필요",ForgeCoolingGuide.Basic),
        new Entry(9,"용뼈","절단 · 가열 · 손잡이 · 판매 보너스",ForgeDragonGuide.Basic)
    });
}
